fn schema<T: schemars::JsonSchema>() -> Option<serde_json::Value> {
    serde_json::to_value(schemars::schema_for!(T)).ok()
}

/// JSON schema of a request type by name; `None` for types without a `JsonSchema` derive.
pub fn schema_of(type_name: &str) -> Option<serde_json::Value> {
    match type_name {
        "CreateRunRequest" => schema::<crate::execution::runs::api::CreateRunRequest>(),
        _ => None,
    }
}
